/* My Wealth 2.3.7 - compact profile switcher, improved local profile manager. */
.profile-picker{position:relative;min-width:0;isolation:isolate;z-index:65}
.profile-picker summary{list-style:none;cursor:pointer;-webkit-tap-highlight-color:transparent}
.profile-picker summary::-webkit-details-marker{display:none}
.profile-trigger{display:flex;align-items:center;gap:10px;border:1px solid #ffffff29;border-radius:14px;background:#ffffff13;color:#fff;padding:10px 11px;min-width:0;transition:background .18s ease,border-color .18s ease,box-shadow .18s ease}
.profile-trigger:hover,.profile-picker[open] .profile-trigger{background:#ffffff20;border-color:#ffffff50}
.profile-trigger:focus-visible{outline:3px solid #8799ff;outline-offset:2px}
.profile-avatar{height:38px;width:38px;display:grid;place-items:center;border-radius:12px;flex:none;background:linear-gradient(140deg,#7188fa,#42b7c1);color:#fff;font-size:13px;font-family:Manrope,system-ui,sans-serif;font-weight:800;letter-spacing:.5px;box-shadow:0 3px 14px #141d4442}
.profile-trigger-copy{min-width:0;display:flex;flex:1;flex-direction:column;align-items:flex-start;gap:3px;max-width:170px}
.profile-trigger-label{font-size:9px;text-transform:uppercase;letter-spacing:.85px;font-weight:750;color:#bbc9e2}
.profile-trigger-name{font-size:13px;line-height:1.2;font-weight:800;text-overflow:ellipsis;overflow:hidden;white-space:nowrap;width:100%;text-align:left}
.profile-caret{flex:none;color:#c8d6ee;font-size:15px;transform:rotate(0);transition:transform .18s ease}
.profile-picker[open] .profile-caret{transform:rotate(180deg)}
.profile-dropdown{position:absolute;left:0;top:calc(100% + 8px);z-index:90;width:min(306px,calc(100vw - 24px));max-height:min(530px,75vh);overflow-y:auto;border:1px solid #e5eaf3;border-radius:17px;background:#fff;color:#202d45;box-shadow:0 20px 55px #0c173b33;padding:9px}
.profile-menu-heading{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:10px 10px 12px;font-size:11px;font-weight:850;color:#8a96aa;letter-spacing:.65px;text-transform:uppercase}
.profile-menu-count{font-size:10px;background:#edf1fb;color:#5a6c89;border-radius:99px;padding:3px 7px;white-space:nowrap}
.profile-option{width:100%;display:flex;align-items:center;gap:10px;border:none;border-radius:11px;background:transparent;color:#2b3954;padding:9px;text-align:left;min-width:0;cursor:pointer}
.profile-option:hover{background:#f1f4fb}.profile-option.current{background:#eef2ff}.profile-option:disabled{opacity:1;cursor:default}
.profile-option .profile-avatar{height:32px;width:32px;border-radius:10px;font-size:11px;box-shadow:none}
.profile-option-main{display:flex;flex-direction:column;flex:1;gap:2px;min-width:0}
.profile-option-name{font-size:12px;font-weight:800;line-height:1.3;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.profile-option-meta{font-size:10px;color:#8794a9}.profile-option-check{color:#5369e9;font-weight:900;font-size:16px}
.profile-menu-tools{display:flex;flex-direction:column;gap:2px;border-top:1px solid #e9edf6;padding:7px 2px 1px;margin-top:7px}
.profile-menu-tool{display:flex;align-items:center;gap:10px;border:0;background:transparent;color:#43526b;border-radius:10px;text-align:left;font-weight:750;font-size:12px;padding:11px 10px;width:100%}
.profile-menu-tool:hover{background:#f1f4fb;color:#455ed2}.profile-menu-tool .tool-symbol{font-size:16px;display:grid;place-items:center;width:20px;flex:none}
.profile-picker--sidebar{margin:1px 11px 13px}.profile-picker--sidebar .profile-trigger{width:100%;text-align:left}.profile-picker--sidebar .profile-trigger-name{white-space:normal;overflow:visible;text-overflow:clip;overflow-wrap:anywhere;line-height:1.35;font-size:12px}
.profile-mobile-controls{display:none}
.profile-picker--mobile{width:max-content;max-width:100%;margin-top:9px}
.profile-picker--mobile .profile-trigger{background:#fff;border-color:#dfe5f1;color:#25334e;box-shadow:0 3px 13px #2638610c;padding:8px 10px;border-radius:13px;max-width:100%}
.profile-picker--mobile .profile-trigger:hover,.profile-picker--mobile[open] .profile-trigger{background:#f6f8ff;border-color:#b6c4f7}
.profile-picker--mobile .profile-trigger-label{color:#8997ac}.profile-picker--mobile .profile-caret{color:#7987a1}
.profile-picker--mobile .profile-dropdown{width:min(305px,calc(100vw - 28px))}
.profile-manager-hero{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:24px 26px;border-radius:18px;background:linear-gradient(115deg,#182746,#2c426d);color:#fff;box-shadow:0 10px 26px #202e4c19}
.profile-manager-hero h2{font-family:Manrope,system-ui,sans-serif;letter-spacing:-.4px;font-size:18px;margin:0 0 6px}.profile-manager-hero p{color:#c9d5eb;font-size:12px;margin:0;line-height:1.65}
.profile-manager-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(245px,1fr));gap:16px}
.profile-manage-card{border:1px solid #e4eaf3;border-radius:16px;background:#fff;padding:19px;box-shadow:var(--shadow);display:flex;flex-direction:column;gap:13px;min-width:0}
.profile-manage-card.is-active{border-color:#a9b9fa;box-shadow:0 12px 30px #566fe112}
.profile-manage-head{display:flex;align-items:center;justify-content:space-between;gap:10px}
.profile-manage-card .profile-avatar{height:46px;width:46px;border-radius:14px;font-size:16px}
.profile-manage-card h3{font-family:Manrope,system-ui,sans-serif;font-size:17px;line-height:1.3;margin:0;overflow-wrap:anywhere}
.profile-manage-card p{font-size:11px;color:var(--sub);line-height:1.5;margin:0}
.profile-manage-actions{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-top:auto;padding-top:6px}
.profile-manager-hint{font-size:12px;color:#61718b;line-height:1.65;background:#f3f6fb;border:1px solid #e5ebf3;border-radius:13px;padding:14px 16px}
@media(max-width:750px){.profile-mobile-controls{display:block;margin:0 0 10px}.profile-picker--mobile .profile-avatar{height:33px;width:33px;font-size:11px}.profile-picker--mobile .profile-trigger-copy{max-width:190px}.profile-manager-grid{grid-template-columns:1fr}.profile-manager-hero{padding:20px;align-items:flex-start;flex-direction:column}.profile-dropdown{box-shadow:0 15px 45px #0b203238}}

</style>
</head>

