function profileControls(){
  ensureProfiles(state);
  return `<div class="profile-switch" aria-label="Profilo patrimoniale"><span class="profile-switch-label">👤 Profilo</span><select id="profileSwitcher" aria-label="Cambia profilo">${state.profilesMeta.map(p=>`<option value="${e(p.id)}" ${p.id===state.activeProfileId?'selected':''}>${e(p.name)}</option>`).join('')}</select><button class="mini-link" data-action="newprofile" title="Nuovo profilo">＋ Nuovo</button></div>`;
}
function profileMobileControls(){
  return `<div class="profile-mobile-controls"><label for="profileSwitcherMobile">Profilo:</label><select id="profileSwitcherMobile" aria-label="Seleziona profilo">${state.profilesMeta.map(p=>`<option value="${e(p.id)}" ${p.id===state.activeProfileId?'selected':''}>${e(p.name)}</option>`).join('')}</select><button type="button" class="mini-link" data-action="newprofile">＋ Nuovo</button></div>`;
}

operations.replace:
function profileInitials(label){
  const words=String(label||'').trim().split(/\s+/).filter(Boolean);
  const initials=(words.length>1?words[0].slice(0,1)+words.at(-1).slice(0,1):(words[0]||'P').slice(0,2));
  return e(initials.toLocaleUpperCase('it'));
}
function profilePicker(variant){
  ensureProfiles(state);
  const name=profileName();
  const prefix=variant==='sidebar'?'profileMenuSidebar':'profileMenuMobile';
  return `<details class="profile-picker profile-picker--${variant}" id="${prefix}">
    <summary class="profile-trigger" aria-label="Profilo attivo: ${e(name)}. Apri l'elenco dei profili">
      <span class="profile-avatar" aria-hidden="true">${profileInitials(name)}</span>
      <span class="profile-trigger-copy"><span class="profile-trigger-label">Profilo attivo</span><strong class="profile-trigger-name">${e(name)}</strong></span>
      <span class="profile-caret" aria-hidden="true">⌄</span>
    </summary>
    <div class="profile-dropdown" role="group" aria-label="Seleziona o gestisci un profilo">
      <div class="profile-menu-heading"><span>I tuoi profili</span><span class="profile-menu-count">${state.profilesMeta.length}</span></div>
      ${state.profilesMeta.map(p=>`<button type="button" class="profile-option ${p.id===state.activeProfileId?'current':''}" data-action="switchprofile" data-id="${e(p.id)}" ${p.id===state.activeProfileId?'disabled aria-current="true"':''}>
        <span class="profile-avatar" aria-hidden="true">${profileInitials(p.name)}</span>
        <span class="profile-option-main"><span class="profile-option-name">${e(p.name)}</span><span class="profile-option-meta">${p.id===PRIMARY_PROFILE_ID?'Profilo principale':'Patrimonio separato'}</span></span>
        ${p.id===state.activeProfileId?'<span class="profile-option-check" aria-label="Attivo">✓</span>':''}
      </button>`).join('')}
      <div class="profile-menu-tools">
        <button type="button" class="profile-menu-tool" data-action="renameprofile" data-id="${e(state.activeProfileId)}"><span class="tool-symbol" aria-hidden="true">✎</span> Rinomina profilo attivo</button>
        <button type="button" class="profile-menu-tool" data-action="newprofile"><span class="tool-symbol" aria-hidden="true">＋</span> Crea nuovo profilo</button>
        <button type="button" class="profile-menu-tool" data-action="nav" data-id="profiles"><span class="tool-symbol" aria-hidden="true">⚙</span> Gestisci tutti i profili</button>
      </div>
    </div>
  </details>`;
}
function profileControls(){return profilePicker('sidebar');}
function profileMobileControls(){return `<div class="profile-mobile-controls">${profilePicker('mobile')}</div>`;}

