  <section class="panel"><div class="panel-head"><h2 class="panel-title">I tuoi profili locali</h2><button class="btn primary small" data-action="newprofile">＋ Crea profilo</button></div>
    <div class="micro">Il profilo attivo viene salvato nel JSON insieme agli altri. Non ci sono account online né password separate: chi accede a questo PC può leggere gli altri profili.</div>
    <div class="rows lower">${state.profilesMeta.map(p=>`<div class="profile-row"><div><strong>${e(p.name)}</strong> ${p.id===state.activeProfileId?'<span class="token green">Attivo</span>':''}<div class="micro">${p.id===PRIMARY_PROFILE_ID?'Profilo principale storico':'Patrimonio indipendente'}</div></div><div class="profile-actions"><button class="btn secondary small" data-action="switchprofile" data-id="${e(p.id)}" ${p.id===state.activeProfileId?'disabled':''}>Apri</button><button class="btn ghost small" data-action="renameprofile" data-id="${e(p.id)}">Rinomina</button>${p.id!==PRIMARY_PROFILE_ID?`<button class="btn warn small" data-action="deleteprofile" data-id="${e(p.id)}">Elimina</button>`:''}</div></div>`).join('')}</div>
